      return;
    }
    await db.insert(deploymentScans).values({
      scanId: scan.scanId,
      deploymentId: scan.deploymentId,
      overallScore: scan.overallScore,
      passed: scan.passed ? 1 : 0,
      checksRun: scan.checksRun,
      checksPassed: scan.checksPassed,
      checksFailed: scan.checksFailed,
      details: scan.details ? JSON.stringify(scan.details) : null,
      createdAt: Date.now(),
    });
  } catch (err) {
