  } catch { return []; }
}

export async function getDeploymentStats() {
  try {
    const db = await getDb();
    const countQuery = sql<number>`COUNT(*)`;
    const [d, s, c, g] = await Promise.all([
      db.select({ count: countQuery }).from(deploymentRecords).then((r) => Number(r[0]?.count ?? 0)),
      db.select({ count: countQuery }).from(deploymentScans).then((r) => Number(r[0]?.count ?? 0)),
      db.select({ count: countQuery }).from(monitorCycles).then((r) => Number(r[0]?.count ?? 0)),
      db.select({ count: countQuery }).from(governanceDeploySnapshots).then((r) => Number(r[0]?.count ?? 0)),
    ]);
    return { totalDeployments: d, totalScans: s, totalMonitorCycles: c, totalGovernanceSnapshots: g };
  } catch {
    return { totalDeployments: 0, totalScans: 0, totalMonitorCycles: 0, totalGovernanceSnapshots: 0 };
  }
}

